import {LIMITS,explanations} from './parser.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let report=null,fileName='',tab='overview',worker=null,processing=false,generation=0,search='',protocol='';
const num=n=>new Intl.NumberFormat().format(n),bytes=n=>n>=1073741824?(n/1073741824).toFixed(2)+' GiB':n>=1048576?(n/1048576).toFixed(2)+' MiB':n>=1024?(n/1024).toFixed(1)+' KiB':num(n)+' B';
const duration=s=>s===null?'Not available':s<1?s.toFixed(3)+' seconds':s<60?s.toFixed(1)+' seconds':s<3600?Math.floor(s/60)+'m '+Math.round(s%60)+'s':Math.floor(s/3600)+'h '+Math.floor(s%3600/60)+'m';
const time=t=>t===null?'No timestamp':Number.isFinite(t)&&Math.abs(t)<8.64e12?new Date(t*1000).toLocaleString():'Timestamp out of range';
function busy(value){processing=value;$('#browse-button').disabled=value;$('#demo-button').disabled=value;$('#cancel-button').hidden=!value;$('#progress').hidden=!value;}
function clear(){generation++;worker?.terminate();worker=null;report=null;fileName='';busy(false);$('#report-section').hidden=true;$('#upload-section').hidden=false;$('#export-button').hidden=true;$('#clear-button').hidden=true;$('#device-count').textContent='';$('#error-box').hidden=true;$('#upload-status').textContent='';$('#file-input').value='';setTab('overview');}
function error(message){busy(false);$('#error-box').textContent=message;$('#error-box').hidden=false;$('#upload-status').textContent='';$('#error-box').scrollIntoView({block:'nearest'});}
async function load(file,demo=false){
  if(processing)return;if(!file)return;if(file.size>LIMITS.bytes){error('This version accepts up to 150 MiB. Split the capture in Wireshark first.');return;}
  const current=++generation;report=null;$('#upload-section').hidden=false;$('#report-section').hidden=true;$('#export-button').hidden=true;$('#clear-button').hidden=true;$('#device-count').textContent='';setTab('overview');busy(true);$('#error-box').hidden=true;$('#upload-status').textContent='Reading your capture…';$('#progress-fill').style.width='3%';
  try{const buffer=await file.arrayBuffer();if(current!==generation)return;$('#upload-status').textContent='Breaking down packets on your computer…';
    worker=new Worker('worker.js',{type:'module'});worker.onmessage=({data})=>{if(current!==generation)return;if(data.progress!==undefined){$('#progress-fill').style.width=data.progress+'%';$('#upload-status').textContent=`Reading packets… ${data.progress}%`;}
      if(data.error){worker?.terminate();worker=null;error(data.error);}if(data.report){report=data.report;fileName=file.name;worker?.terminate();worker=null;busy(false);$('#upload-section').hidden=true;$('#report-section').hidden=false;$('#export-button').hidden=false;$('#clear-button').hidden=false;$('#demo-badge').hidden=!demo;$('#capture-name').textContent=fileName;$('#capture-meta').textContent=`${report.format} · ${bytes(file.size)} file · ${time(report.stats.start)} · ${num(report.stats.packets)} packets analyzed`;$('#device-count').textContent=num(report.hosts.length);setTab('overview');}}
    worker.onerror=()=>{worker?.terminate();worker=null;error('The capture reader could not start. Use the hosted app or run Start Packet Lens.cmd rather than opening the HTML file directly.');};worker.postMessage({buffer},[buffer]);
  }catch(e){if(current===generation)error(e.message||'Unable to read the file.');}
}
$('#browse-button').onclick=()=>$('#file-input').click();$('#new-button').onclick=()=>$('#file-input').click();$('#file-input').onchange=e=>{const file=e.target.files[0];e.target.value='';load(file);};$('#clear-button').onclick=clear;$('#cancel-button').onclick=()=>{generation++;worker?.terminate();worker=null;busy(false);$('#upload-status').textContent='Analysis cancelled.';};
$('#demo-button').onclick=async()=>{try{const r=await fetch('demo.pcap');if(!r.ok)throw Error('Demo capture unavailable.');load(new File([await r.arrayBuffer()],'example-office-network.pcap'),true);}catch(e){error(e.message);}};
const drop=$('#dropzone');['dragenter','dragover'].forEach(name=>drop.addEventListener(name,e=>{e.preventDefault();drop.classList.add('dragover');}));['dragleave','drop'].forEach(name=>drop.addEventListener(name,e=>{e.preventDefault();drop.classList.remove('dragover');}));document.addEventListener('dragover',e=>e.preventDefault());document.addEventListener('drop',e=>{e.preventDefault();load(e.dataTransfer.files[0]);});document.addEventListener('paste',e=>{if(e.clipboardData?.files.length){e.preventDefault();load(e.clipboardData.files[0]);}});
$('#help-button').onclick=()=>$('#help-dialog').showModal();$('#close-help').onclick=$('#help-done').onclick=()=>$('#help-dialog').close();
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{setTab(b.dataset.tab);if(!report)$('#upload-status').textContent='Choose a capture or try the demo to explore your network.';});
const titles={overview:['Your network, explained.','The big picture, with the details that matter.'],devices:['Meet the devices.','Observed IP addresses and how much traffic each one exchanged.'],connections:['Follow the conversation.','See which endpoints communicated, on which ports, and how much.'],domains:['Where your network went.','Names visible in DNS, HTTP, and complete TLS handshakes.'],packets:['A closer look at the packets.','A readable view of the first 2,500 packets in your capture.']};
function setTab(name){tab=name;search='';protocol='';document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#page-title').textContent=report?titles[tab][0]:'Understand your network.';$('#page-subtitle').textContent=report?titles[tab][1]:'Turn a Wireshark capture into a story you can actually read.';if(report)render();}
function filterFor(ip){return (ip.includes(':')?'ipv6.addr':'ip.addr')+' == '+ip;}
function copyButton(filter){return `<button class="copy-filter" data-copy="${esc(filter)}">Copy filter</button>`;}
function bindCopy(){document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);b.textContent='Copied';setTimeout(()=>b.textContent='Copy filter',1500);}catch{window.prompt('Copy this Wireshark display filter:',b.dataset.copy);}});}
function overview(){const r=report,s=r.stats,total=Math.max(1,s.bytes),span=s.start===null?null:s.end-s.start,busiest=r.hosts[0],largest=r.protocols[0];
  const summary=`This capture contains ${num(s.packets)} packets over ${duration(span)}, representing ${bytes(s.bytes)} of original packet lengths. We observed ${num(r.hosts.length)} IP addresses and ${num(r.flows.length)} connection pairs.${largest?` The largest traffic category was ${largest.name} (${Math.round(largest.bytes/total*100)}% of packet bytes).`:''}${busiest?` The busiest address was ${busiest.ip}, with ${bytes(busiest.sent+busiest.received)} sent and received.`:''}${r.domains.length?` ${num(r.domains.length)} domain names were visible.`:' No domain names were visible in the supported decoders.'}`;
  const max=Math.max(1,...r.timeline.map(b=>b.bytes));
  return `<div class="stats-grid"><div class="stat"><span>PACKETS ANALYZED</span><strong>${num(s.packets)}</strong><small>Every record within the file limits</small></div><div class="stat"><span>TRAFFIC VOLUME</span><strong>${bytes(s.bytes)}</strong><small>Sum of original packet lengths</small></div><div class="stat"><span>OBSERVED ADDRESSES</span><strong>${num(r.hosts.length)}</strong><small>IP addresses, not physical machines</small></div><div class="stat"><span>CAPTURE DURATION</span><strong>${span===null?'—':duration(span)}</strong><small>${s.missingTime?'Some timestamps unavailable':'First to last packet timestamp'}</small></div></div><article class="card summary"><h3>⌁ &nbsp; Here’s what your capture tells us</h3><p>${esc(summary)}</p></article><div class="report-grid"><article class="card"><div class="card-heading"><h3>Traffic over time</h3><small>Packet bytes · 60 intervals</small></div>${s.start===null?'<p class="empty">This capture has no timestamps.</p>':`<div class="traffic-chart" role="img" aria-label="Traffic volume across 60 time intervals">${r.timeline.map(b=>`<div style="height:${Math.max(1,b.bytes/max*100)}%" title="Interval ${b.index+1}: ${bytes(b.bytes)}"></div>`).join('')}</div><div class="chart-axis"><span>${esc(time(s.start))}</span><span>${esc(time(s.end))}</span></div>`}</article><article class="card"><div class="card-heading"><h3>What the traffic is doing</h3><small>Share of bytes</small></div>${r.protocols.slice(0,7).map(p=>`<div class="protocol-row" title="${esc(explanations[p.name]||'Inferred from packet headers.')} — ${bytes(p.bytes)}"><span>${esc(p.name)}</span><div class="bar-bg"><div class="bar-fill" style="width:${p.bytes/total*100}%"></div></div><span>${(p.bytes/total*100).toFixed(1)}%</span></div>`).join('')}</article></div><article class="card"><div class="card-heading"><h3>Worth a closer look</h3><small>Clues from this capture</small></div>${r.findings.map(f=>`<div class="finding ${f.level}"><div class="finding-icon">${f.level==='info'?'i':'!'}</div><div><h4>${esc(f.title)}</h4><p>${esc(f.detail)}</p><div class="next"><strong>Next step:</strong> ${esc(f.next)}</div>${f.filter?`<div class="filter-line"><code>${esc(f.filter)}</code>${copyButton(f.filter)}</div>`:''}</div></div>`).join('')}</article><article class="card coverage"><div class="card-heading"><h3>How much could we see?</h3><small>Read the evidence in context</small></div>${r.warnings.length?`<ul>${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:'All capture records were read. No truncated frames or unknown protocol categories were observed.'}<p>This is a header-based explanation, not a health or security verdict. Encrypted contents, stream reassembly, packet-loss analysis, and application identification are outside this version. Service names are inferred from ports unless readable headers provide stronger evidence. Traffic seen here reflects only the capture location and time.</p></article><article class="card"><div class="card-heading"><h3>A little protocol translation</h3></div><div class="glossary">${r.protocols.slice(0,8).map(p=>`<div><strong>${esc(p.name)}</strong><p>${esc(explanations[p.name]||'Traffic grouped by its transport headers or common service port.')}</p></div>`).join('')}</div></article>`;
}
const notes={devices:'Each row is an IP address seen in packet headers or DNS answers. One machine can have several addresses. Bytes include full original packet lengths; peer counts are capped at 1,000 per address.',connections:'A connection pair groups both directions by IP addresses, ports, and transport. Separate sessions reusing the same pair are combined. Service labels are inferred from ports; a missing reply can also reflect one-way capture visibility.',domains:'These are visible name observations, not a browsing history. DNS lookups do not prove a connection happened. IP associations come from captured DNS answers. TLS names require a complete ClientHello in one packet.',packets:'Showing the first 2,500 capture records. Summary totals include every record within the file limits. This explorer shows headers and short descriptions, without packet bodies.'};
function rowData(){let rows=tab==='devices'?report.hosts:tab==='connections'?report.flows:tab==='domains'?report.domains:report.samples;return rows.filter(r=>(!search||JSON.stringify(r).toLowerCase().includes(search.toLowerCase()))&&(!protocol||r.protocol===protocol));}
function tableRows(){const rows=rowData(),shown=rows.slice(0,500);let heads,body;
  if(tab==='devices'){heads=['ADDRESS / VISIBLE NAMES','SCOPE','SENT','RECEIVED','PACKETS','PEERS','WIRESHARK'];body=shown.map(h=>`<tr><td class="mono">${esc(h.ip)}<small>${esc(h.names.slice(0,3).join(', ')||h.macs.join(', ')||'Name not visible')}</small></td><td><span class="tag">${esc(h.kind)}</span></td><td>${bytes(h.sent)}</td><td>${bytes(h.received)}</td><td>${num(h.packets)}</td><td>${num(h.peers)}${h.peers===1000?'+':''}</td><td>${copyButton(filterFor(h.ip))}</td></tr>`).join('');}
  if(tab==='connections'){heads=['ENDPOINT A','ENDPOINT B','SERVICE / TRANSPORT','PACKETS','VOLUME','OBSERVED CLUES'];body=shown.map(f=>`<tr><td class="mono">${esc(f.src)}<small>Port ${f.sport}</small></td><td class="mono">${esc(f.dst)}<small>Port ${f.dport}</small></td><td><span class="tag">${esc(f.protocol)}</span><small>${esc(f.service)} · ${f.transport}</small></td><td>${num(f.packets)}</td><td>${bytes(f.bytes)}</td><td class="connection-label">${f.resets?`${num(f.resets)} reset(s)`:f.syn>=3&&!f.responsePackets?'Repeated SYN; no visible reply':f.responsePackets?'Both directions visible':'One direction visible'}</td></tr>`).join('');}
  if(tab==='domains'){heads=['DOMAIN','OBSERVED IN','LOOKUPS','RESPONSES','ERRORS','DNS ANSWER ADDRESSES'];body=shown.map(d=>`<tr><td class="mono">${esc(d.name)}</td><td>${d.sources.map(s=>`<span class="tag">${esc(s)}</span>`).join(' ')}</td><td>${num(d.queries)}</td><td>${num(d.responses)}</td><td>${num(d.failures)}</td><td class="mono">${esc(d.ips.join(', ')||'Not captured')}</td></tr>`).join('');}
  if(tab==='packets'){heads=['#','TIME FROM START','SOURCE → DESTINATION','PROTOCOL','LENGTH','WHAT HAPPENED'];body=shown.map(p=>`<tr><td>${p.number}</td><td>${p.time===null||report.stats.start===null?'—':(p.time-report.stats.start).toFixed(6)+'s'}</td><td class="mono">${esc(p.src)}<small>→ ${esc(p.dst)}</small></td><td><span class="tag">${esc(p.protocol)}</span></td><td>${bytes(p.length)}</td><td>${esc(p.info)}</td></tr>`).join('');}
  return {html:`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table>${!shown.length?`<div class="empty">${tab==='domains'&&!report.domains.length?'No readable domain names were found. Encrypted DNS, cached lookups, or an incomplete capture can explain this.':'No matching records. Try another search.'}</div>`:''}</div>${rows.length>500?'<p class="overflow-note">Showing the first 500 matches. Narrow the search to explore more; the exported report includes the full available lists.</p>':''}`,count:rows.length};
}
function render(){if(tab==='overview'){$('#report-content').innerHTML=overview();bindCopy();return;}
  const table=tableRows();$('#report-content').innerHTML=`<article class="card"><p class="table-note">${notes[tab]}</p><div class="toolbar"><input id="table-search" type="search" aria-label="Search records" placeholder="Search ${tab}…">${['connections','packets'].includes(tab)?`<select id="protocol-filter" aria-label="Filter by protocol"><option value="">All protocols</option>${[...new Set((tab==='connections'?report.flows:report.samples).map(r=>r.protocol))].sort().map(p=>`<option>${esc(p)}</option>`).join('')}</select>`:''}<span id="match-count">${num(table.count)} records</span></div><div id="table-content">${table.html}</div></article>`;
  const refresh=()=>{const t=tableRows();$('#table-content').innerHTML=t.html;$('#match-count').textContent=num(t.count)+' records';bindCopy();};$('#table-search').oninput=e=>{search=e.target.value;refresh();};if($('#protocol-filter'))$('#protocol-filter').onchange=e=>{protocol=e.target.value;refresh();};bindCopy();
}
$('#export-button').onclick=()=>{if(!report)return;const s=report.stats,summary=[`PACKET LENS REPORT — ${fileName}`,`Generated: ${new Date().toLocaleString()}`,`Format: ${report.format}`,`Packets: ${num(s.packets)} | Original packet bytes: ${bytes(s.bytes)}`,`Time: ${time(s.start)} → ${time(s.end)}`,`Addresses: ${num(report.hosts.length)} | Connection pairs: ${num(report.flows.length)}`,`\nFINDINGS`,...report.findings.map(f=>`${f.title}\n${f.detail}\nNext: ${f.next}${f.filter?'\nWireshark filter: '+f.filter:''}`),`\nCAPTURE LIMITATIONS`,...report.warnings,'Header-based analysis; no decryption, stream reassembly, application certainty, or health/security verdict. Service labels may be inferred from ports. Separate sessions sharing the same endpoint pair are grouped.',`\nFull structured analysis follows (packet explorer limited to the first 2,500 records):`,JSON.stringify(report,null,2)].join('\n\n');const url=URL.createObjectURL(new Blob([summary],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=fileName.replace(/\.[^.]+$/,'')+'-packet-lens-report.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
